import com.ezylang.evalex.parser.Tokenizer;
import com.ezylang.evalex.parser.Token;
import com.ezylang.evalex.parser.ParseException;
import org.junit.Assert;
import org.junit.Test;

public class TokenizerTest {

	@Test
	public void parseSimpleExpressionTest() {
		String expression = "3+4";
		Tokenizer tokenizer = new Tokenizer(expression, null);
		try {
			Assert.assertEquals(3, tokenizer.parse().size());
		} catch (ParseException e) {
			Assert.fail(e.getMessage());
		}
	}

	@Test(expected = ParseException.class)
	public void parseWhenExpressionHasInvalidCharacterTest() throws ParseException {
		String expression = "3+%4";
		Tokenizer tokenizer = new Tokenizer(expression, null);
		tokenizer.parse();
	}

	@Test
	public void parseStringLiteralWhenStringIsEmptyTest() throws ParseException {
		String expression = "''";
		Tokenizer tokenizer = new Tokenizer(expression, null);
		Token token = tokenizer.parseStringLiteral();
		Assert.assertEquals(Token.TokenType.STRING, token.getType());
		Assert.assertEquals("", token.getValue());
	}

	@Test
	public void parseStringLiteralWhenStringHasValueTest() throws ParseException {
		String expression = "'HelloWorld'";
		Tokenizer tokenizer = new Tokenizer(expression, null);
		Token token = tokenizer.parseStringLiteral();
		Assert.assertEquals(Token.TokenType.STRING, token.getType());
		Assert.assertEquals("HelloWorld", token.getValue());
	}

	@Test(expected = ParseException.class)
	public void parseStringLiteralWhenStringIsNotTerminatedTest() throws ParseException {
		String expression = "'HelloWorld";
		Tokenizer tokenizer = new Tokenizer(expression, null);
		tokenizer.parseStringLiteral();
	}
}
